// Imperative Approach (Vanilla JS / jQuery Style):
const btn = document.querySelector("#counter-btn");
const display = document.querySelector("#counter-val");
let count = 0;
btn.addEventListener("click", () => {
  count++;
  display.textContent = count; // Manual, fragile DOM write
  if (count > 5) display.style.color = "red";
});

// Declarative Approach (React):
import { useState } from 'react';

function Counter() {
  const [count, setCount] = useState(0);
  return (
    <div>
      <span style={{ color: count > 5 ? 'red' : 'white' }}>{count}</span>
      <button onClick={() => setCount(c => c + 1)}>Increment</button>
    </div>
  );
}

