import React, { useState, createContext, useContext } from 'react';

const TabsContext = createContext(null);

export function Tabs({ defaultTab, children }) {
  const [activeTab, setActiveTab] = useState(defaultTab);
  return (
    <TabsContext.Provider value={{ activeTab, setActiveTab }}>
      <div className="tabs-container">{children}</div>
    </TabsContext.Provider>
  );
}

Tabs.List = function TabList({ children }) {
  return <div className="tab-buttons-bar" role="tablist">{children}</div>;
};

Tabs.Trigger = function TabTrigger({ value, children }) {
  const { activeTab, setActiveTab } = useContext(TabsContext);
  const isSelected = activeTab === value;
  return (
    <button
      role="tab"
      aria-selected={isSelected}
      className={isSelected ? 'tab-trigger active' : 'tab-trigger'}
      onClick={() => setActiveTab(value)}
    >
      {children}
    </button>
  );
};

Tabs.Content = function TabContent({ value, children }) {
  const { activeTab } = useContext(TabsContext);
  if (activeTab !== value) return null;
  return <div role="tabpanel" className="tab-panel">{children}</div>;
};

import { useState } from 'react';

function BatchingDemo() {
  const [count, setCount] = useState(0);

  function handleDirectIncrements() {
    // ❌ WRONG: each uses the snapshot count (0)
    // setCount(count + 1); // queues: next = 0 + 1
    // setCount(count + 1); // queues: next = 0 + 1
    // setCount(count + 1); // queues: next = 0 + 1
    // Result: count becomes 1, NOT 3!

    // ✅ CORRECT: Functional updates receive the pending state queue
    setCount(prev => prev + 1); // 0 -> 1
    setCount(prev => prev + 1); // 1 -> 2
    setCount(prev => prev + 1); // 2 -> 3
    // Result: count becomes 3!
  }

  return <button onClick={handleDirectIncrements}>Count: {count}</button>;
}

