import { useState } from 'react';

export function RegistrationForm({ onSubmit }) {
  const [values, setValues] = useState({ username: '', email: '', role: 'developer' });
  const [touched, setTouched] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  // Derived validation errors (computed during render):
  const errors = {
    username: values.username.length < 3 ? 'Username must be at least 3 characters' : null,
    email: !/\S+@\S+\.\S+/.test(values.email) ? 'Enter a valid email address' : null
  };
  const isValid = !errors.username && !errors.email;

  function handleChange(e) {
    const { name, value } = e.target;
    setValues(prev => ({ ...prev, [name]: value }));
  }

  function handleBlur(e) {
    const { name } = e.target;
    setTouched(prev => ({ ...prev, [name]: true }));
  }

  async function handleSubmit(e) {
    e.preventDefault();
    setTouched({ username: true, email: true });
    if (!isValid) return;

    setIsSubmitting(true);
    try {
      await onSubmit(values);
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <form onSubmit={handleSubmit} className="form-card" noValidate>
      <div className="field-group">
        <label htmlFor="reg-username">Username</label>
        <input
          id="reg-username"
          name="username"
          value={values.username}
          onChange={handleChange}
          onBlur={handleBlur}
          aria-invalid={Boolean(touched.username && errors.username)}
        />
        {touched.username && errors.username && (
          <span className="field-error" role="alert">{errors.username}</span>
        )}
      </div>

      <div className="field-group">
        <label htmlFor="reg-email">Email</label>
        <input
          id="reg-email"
          name="email"
          type="email"
          value={values.email}
          onChange={handleChange}
          onBlur={handleBlur}
          aria-invalid={Boolean(touched.email && errors.email)}
        />
        {touched.email && errors.email && (
          <span className="field-error" role="alert">{errors.email}</span>
        )}
      </div>

      <button type="submit" disabled={isSubmitting || (Object.keys(touched).length > 0 && !isValid)}>
        {isSubmitting ? 'Registering...' : 'Complete Registration'}
      </button>
    </form>
  );
}

