import { useState, useReducer, useRef, useContext, createContext } from 'react';

// 1. useReducer state machine:
function counterReducer(state, action) {
  switch (action.type) {
    case 'INC': return { count: state.count + 1 };
    case 'DEC': return { count: Math.max(0, state.count - 1) };
    case 'RESET': return { count: 0 };
    default: return state;
  }
}

// 2. Context setup:
const ThemeContext = createContext('dark');

export function CoreHooksDemo() {
  const [state, dispatch] = useReducer(counterReducer, { count: 0 });
  const theme = useContext(ThemeContext);
  const renderCountRef = useRef(0);

  // Ref mutation: Does NOT cause re-render!
  renderCountRef.current += 1;

  return (
    <div className={`card theme-${theme}`}>
      <p>Count: {state.count} (Rendered {renderCountRef.current} times)</p>
      <button onClick={() => dispatch({ type: 'INC' })}>+</button>
      <button onClick={() => dispatch({ type: 'DEC' })}>-</button>
      <button onClick={() => dispatch({ type: 'RESET' })}>Reset</button>
    </div>
  );
}

import { useState, useTransition, useDeferredValue, useId } from 'react';

function SearchFilter({ allItems }) {
  const [query, setQuery] = useState('');
  const [isPending, startTransition] = useTransition();
  const inputId = useId();

  // Urgent update: Keep the typing input snappy
  function handleChange(e) {
    const val = e.target.value;
    // Low-priority transition: Filter calculation deferred
    startTransition(() => {
      setQuery(val);
    });
  }

  const filtered = allItems.filter(item => item.name.toLowerCase().includes(query.toLowerCase()));

  return (
    <div>
      <label htmlFor={inputId}>Search Records:</label>
      <input id={inputId} onChange={handleChange} placeholder="Type to filter..." />
      {isPending && <span className="spinner">Updating list...</span>}
      <ul>
        {filtered.slice(0, 20).map(item => <li key={item.id}>{item.name}</li>)}
      </ul>
    </div>
  );
}

// ❌ ANTI-PATTERN: Using useEffect for user event side-effects
function CheckoutBad({ cart, onBuy }) {
  const [submitted, setSubmitted] = useState(false);

  // Fragile effect watching state toggles
  useEffect(() => {
    if (submitted) {
      api.post('/checkout', cart);
    }
  }, [submitted, cart]);

