// ✅ BEST PRACTICE: Execute side-effects directly inside event handlers
function CheckoutGood({ cart, onBuy }) {
  const [isSubmitting, setIsSubmitting] = useState(false);

  async function handleCheckout() {
    setIsSubmitting(true);
    try {
      await api.post('/checkout', cart);
      onBuy();
    } finally {
      setIsSubmitting(false);
    }
  }

  return (
    <button onClick={handleCheckout} disabled={isSubmitting}>
      {isSubmitting ? 'Processing...' : 'Checkout'}
    </button>
  );
}

import { useEffect, useState } from 'react';

function LivePriceTicker({ symbol }) {
  const [price, setPrice] = useState(null);

  useEffect(() => {
    // 1. Setup Phase: Connect to external WebSocket
    const socket = new WebSocket(`wss://stream.market.com/quotes?symbol=${symbol}`);

    socket.onmessage = (event) => {
      const data = JSON.parse(event.data);
      setPrice(data.price);
    };

    // 2. Cleanup Phase: Disconnect cleanly when symbol changes or unmounts
    return () => {
      socket.close();
    };
  }, [symbol]); // Re-runs cleanly when symbol changes!

  return <div>{symbol}: {price ? `$${price}` : 'Connecting...'}</div>;
}

import { useState, useEffect } from 'react';

function UserSearch({ query }) {
  const [results, setResults] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (!query.trim()) {
      setResults([]);
      return;
    }

    // Create an AbortController instance
    const controller = new AbortController();
    const { signal } = controller;

    async function fetchUsers() {
      setIsLoading(true);
      try {
        const res = await fetch(`/api/users/search?q=${encodeURIComponent(query)}`, { signal });
        const data = await res.json();
        setResults(data);
      } catch (err) {
        if (err.name !== 'AbortError') {
          console.error("Fetch error:", err);
        }
      } finally {
        setIsLoading(false);
      }
    }

    fetchUsers();

    // Cleanup: Abort in-flight network request if query changes before response arrives!
    return () => {
      controller.abort();
    };
  }, [query]);

  return (
    <div>
      {isLoading && <p>Searching...</p>}
      <ul>
        {results.map(u => <li key={u.id}>{u.name}</li>)}
      </ul>
    </div>
  );
}
